mapper.select:
SELECT e.id, e.laboratory_id, e.category_id, e.name, e.description, e.location, e.image,
       e.usage_requirement, e.status, e.booking_enabled, e.create_time, e.update_time,
       l.name AS laboratory_name, l.campus, l.building, l.room,
       c.name AS category_name
FROM tb_equipment e
LEFT JOIN tb_laboratory l ON e.laboratory_id = l.id
LEFT JOIN tb_equipment_category c ON e.category_id = c.id


        AND e.laboratory_id = #{q.laboratoryId}


        AND e.category_id = #{q.categoryId}


        AND l.campus = #{q.campus}


        AND e.name LIKE CONCAT('%', #{q.name}, '%')


        AND e.status = #{q.status}


        AND e.booking_enabled = #{q.bookingEnabled}


ORDER BY e.id DESC
